document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>showPage(t.dataset.page));document.getElementById('moreToggle').onclick=()=>{const m=document.getElementById('more'),open=m.classList.toggle('open');document.getElementById('moreToggle').classList.toggle('active',open);if(open)requestAnimationFrame(()=>m.scrollIntoView({behavior:'smooth',block:'nearest'}))};
function loadHidden(){try{return new Set(JSON.parse(localStorage.getItem(layoutKey)||'[]'))}catch(_){return new Set()}}let hidden=loadHidden();
