function cycle3d(){const s=window.remoteState;if(!s||!s.StereoAvailable)return;const modes=['off','auto','sbs','tab'],i=Math.max(0,modes.indexOf(s.StereoMode));cmd('stereo','&mode='+modes[(i+1)%modes.length])}
